<script setup>
import { computed,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import StatusTag from '../components/StatusTag.vue';import { TASK_STATUS,getTaskById,getTaskTypeText } from '../mock/tasks.js'
const route=useRoute();const router=useRouter();const advisorId='T001';const keyword=ref('');const filter=ref('');const major=ref('');const allowed=[TASK_STATUS.PUBLISHED,TASK_STATUS.SELECTING,TASK_STATUS.SELECTED,TASK_STATUS.LEADER_ASSIGNED,TASK_STATUS.IN_PROGRESS];const task=computed(()=>{const item=getTaskById(route.params.id);return item?.advisorId===advisorId&&allowed.includes(item.status)?item:null});const majors=computed(()=>[...new Set((task.value?.applicants||[]).map(item=>item.major).filter(Boolean))]);const applicants=computed(()=>{const search=keyword.value.trim().toLowerCase();return(task.value?.applicants||[]).filter(item=>{const state=item.selected||item.applyStatus==='selected'?'selected':['applied','pending_selection'].includes(item.applyStatus)?'pending':'not_selected';return(!filter.value||filter.value===state)&&(!major.value||item.major===major.value)&&(!search||[item.studentName,item.studentId].some(value=>String(value).toLowerCase().includes(search)))})});const selectedCount=computed(()=>(task.value?.applicants||[]).filter(item=>item.selected||item.applyStatus==='selected').length);const rejectedCount=computed(()=>(task.value?.applicants||[]).filter(item=>item.applyStatus==='not_selected').length);function back(){router.push(`/teacher/tasks/${route.params.id}`)}function results(){router.push('/teacher/confirm/results')}
</script>
<template><main class="page"><div class="content"><template v-if="task"><header><div><p class="eyebrow">T103 · APPLICANTS</p><h1>报名学生列表</h1><p>{{ task.title }} · {{ getTaskTypeText(task.taskType) }}</p></div><StatusTag :status="task.status" /></header><section class="stats"><article><span>报名人数</span><strong>{{ task.applicants?.length||0 }}</strong></article><article><span>已选中人数</span><strong>{{ selectedCount }}</strong></article><article><span>未选中人数</span><strong>{{ rejectedCount }}</strong></article><article><span>当前队长</span><strong>{{ task.leaderName||'未指定' }}</strong></article></section><section class="filters"><label><span>搜索</span><input v-model="keyword" placeholder="学生姓名或学号" /></label><label><span>专业</span><select v-model="major"><option value="">全部专业</option><option v-for="value in majors" :key="value" :value="value">{{ value }}</option></select></label><label><span>筛选状态</span><select v-model="filter"><option value="">全部</option><option value="pending">待筛选</option><option value="selected">已选中</option><option value="not_selected">未选中</option></select></label></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>学生姓名</th><th>学号</th><th>学院</th><th>专业</th><th>班级</th><th>报名时间</th><th>报名状态</th><th>是否选中</th><th>是否队长</th><th>筛选意见</th><th>成果提交状态</th></tr></thead><tbody><tr v-for="item in applicants" :key="item.studentId"><td>{{ item.studentName }}</td><td>{{ item.studentId }}</td><td>{{ item.college||'--' }}</td><td>{{ item.major||'--' }}</td><td>{{ item.className||'--' }}</td><td>{{ item.applyTime }}</td><td><StatusTag :status="item.applyStatus==='selected'?'confirmed':item.applyStatus==='not_selected'?'rejected':'pending'" :text="item.applyStatus==='selected'?'已选中':item.applyStatus==='not_selected'?'未选中':'待筛选'" /></td><td>{{ item.selected?'是':'否' }}</td><td>{{ item.isLeader?'是':'否' }}</td><td>{{ item.selectionComment||'--' }}</td><td><StatusTag status="pending" text="未提交" /></td></tr><tr v-if="!applicants.length"><td class="empty" colspan="11">{{ task.applicants?.length?'没有符合筛选条件的学生。':'暂无报名学生。' }}</td></tr></tbody></table></div></section><div class="actions"><button @click="back">返回</button><RouterLink :to="`/teacher/tasks/${task.taskId}/applicants/select`">筛选学生</RouterLink><RouterLink :to="`/teacher/tasks/${task.taskId}/leader`">指定队长</RouterLink><button @click="results">查看成果</button></div></template><section v-else class="panel empty">无权访问或任务状态不支持报名管理。</section></div></main></template>
<style scoped>.page{min-height:100vh;padding:40px 24px;background:#f3f6fb}.content{width:min(100%,1450px);margin:auto}header{display:flex;justify-content:space-between;gap:20px;margin-bottom:20px}h1{margin:0}header p{color:#64748b}.eyebrow{margin:0 0 6px;color:#2563eb!important;font-size:12px;font-weight:800;letter-spacing:.12em}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.stats article{padding:18px;border:1px solid #dbeafe;border-radius:12px;background:#fff}.stats span,.stats strong{display:block}.stats span{color:#64748b}.stats strong{margin-top:7px;font-size:24px}.filters{display:grid;grid-template-columns:1fr 260px 260px;gap:16px;margin-bottom:18px;padding:18px;border:1px solid #e2e8f0;border-radius:14px;background:#fff}.filters span{display:block;margin-bottom:7px;font-weight:700}.filters input,.filters select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;font:inherit}.panel{overflow:hidden;border:1px solid #e2e8f0;border-radius:14px;background:#fff}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #e2e8f0;text-align:left;white-space:nowrap}th{background:#f8fafc}.empty{padding:34px;text-align:center;color:#64748b}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}.actions a,.actions button{padding:10px 16px;border:1px solid #cbd5e1;border-radius:9px;color:#2563eb;background:#fff;font:inherit;font-weight:700;text-decoration:none}@media(max-width:700px){.page{padding:24px 14px}header{flex-direction:column}.stats,.filters{grid-template-columns:1fr}.actions{flex-wrap:wrap}}</style>
